('default', 'Prefix for all category pages. Default <code>category</code> &rarr; <code>/category/slug/</code>. If left empty, categories are accessible <strong>directly at root</strong> &rarr; <code>/slug/</code> (without prefix). The category index (listing all categories) is not available when the prefix is empty. To configure this together with the <code>%cat%</code> token in posts, ensure the category path is empty so post URLs like <code>/category-slug/post-slug/</code> can work.', 'Präfix für alle Kategorieseiten. Standardmäßig <code>category</code> → <code>/category/slug/</code>. Wenn leer gelassen, sind Kategorien <strong>direkt im Stammverzeichnis</strong> zugänglich → <code>/slug/</code> (ohne Präfix). Der Kategorieindex (der alle Kategorien auflistet) ist nicht verfügbar, wenn das Präfix leer ist. Um dies zusammen mit dem <code>%cat%</code>-Token in Beiträgen zu konfigurieren, stellen Sie sicher, dass der Kategoriepfad leer ist, damit Beitrags-URLs wie <code>/category-slug/post-slug/</code> funktionieren können.', 'de'),
