('default', 'Digital Education Transformation in Indonesia 2026', 'Digitale Bildungstransformation in Indonesien 2026', 'de'),
('default', 'The government officially launched a school digitalization program covering 50,000 educational institutions across Indonesia. The program aims to improve access and quality of technology-based learning.', 'Pemerintah resmi meluncurkan program digitalisasi sekolah yang mencakup 50.000 institusi pendidikan di seluruh Indonesia. Program ini bertujuan meningkatkan akses dan kualitas pembelajaran berbasis teknologi.', 'id'),
('default', 'The government officially launched a school digitalization program covering 50,000 educational institutions across Indonesia. The program aims to improve access and quality of technology-based learning.', 'Die Regierung startete offiziell ein Schuldigitalisierungsprogramm, das 50.000 Bildungseinrichtungen in ganz Indonesien umfasst. Das Programm zielt darauf ab, den Zugang und die Qualität technologiebasierten Lernens zu verbessern.', 'de'),
